import React, { useState, useRef, useEffect } from 'react';
import ReactMarkdown from 'react-markdown';
import './App.css';

function App() {
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState([]);
  const [isStreaming, setIsStreaming] = useState(false);
  const messagesEndRef = useRef(null);
  const textareaRef = useRef(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isStreaming]);

  // Adjust textarea height
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${textareaRef.current.scrollHeight}px`;
    }
  }, [input]);

  const sendMessage = async () => {
    if (!input.trim() || isStreaming) return;

    const currentInput = input;
    const userMsg = { role: 'user', content: currentInput };
    setMessages(prev => [...prev, userMsg, { role: 'assistant', content: '' }]);
    setInput('');
    setIsStreaming(true);

    try {
      const response = await fetch('http://localhost:8000/chat/stream', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: currentInput }),
      });

      const reader = response.body.getReader();
      const decoder = new TextDecoder("utf-8");
      let done = false;

      while (!done) {
        const { value, done: readerDone } = await reader.read();
        done = readerDone;

        if (value) {
          const chunk = decoder.decode(value, { stream: true });
          setMessages(prev => {
            const newMsgs = [...prev];
            newMsgs[newMsgs.length - 1].content += chunk;
            return [...newMsgs];
          });
        }
      }
    } catch (error) {
      console.error("Gemini API Error:", error);
    } finally {
      setIsStreaming(false);
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };

  const renderMessageContent = (content) => {
    // 마크다운 형식으로 넘어온 <think> 처리
    const thinkMatch = content.match(/<think>([\s\S]*?)(?:<\/think>|$)/);
    const hasThink = !!thinkMatch;

    let answerText = content;
    let thinkText = '';

    if (hasThink) {
      thinkText = thinkMatch[1];
      const endThinkIdx = content.indexOf('</think>');
      if (endThinkIdx !== -1) {
         answerText = content.substring(endThinkIdx + 8).trimStart();
      } else {
         answerText = ''; // 아직 생각 중일 때
      }
    }

    return (
      <>
        {hasThink && (
          <details className="think-box" open={!content.includes('</think>')}>
            <summary className="think-summary">
              {content.includes('</think>') ? '🤔 생각 과정 접기/펴기' : '🤔 생각 중...'}
            </summary>
            <div className="think-content">
              <ReactMarkdown>{thinkText}</ReactMarkdown>
            </div>
          </details>
        )}
        {answerText && (
          <div className="answer-content">
            <ReactMarkdown>{answerText}</ReactMarkdown>
          </div>
        )}
      </>
    );
  };

  return (
    <div className="chat-container">
      <div className="chat-window">
        {messages.length === 0 ? (
          <div className="empty-state">
            <h1>안녕하세요!</h1>
            <p>무엇이든 물어보세요.</p>
          </div>
        ) : (
          messages.map((msg, idx) => (
            <div key={idx} className={`message-wrapper ${msg.role}`}>
              <div className="message-content">
                <div className={`avatar ${msg.role}`}>
                  {msg.role === 'user' ? '나' : 'C'}
                </div>
                <div className="text-content">
                  {msg.role === 'assistant' ? (
                    renderMessageContent(msg.content)
                  ) : (
                    <div style={{ whiteSpace: 'pre-wrap' }}>{msg.content}</div>
                  )}
                </div>
              </div>
            </div>
          ))
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="input-container">
        <div className="input-box">
          <textarea
            ref={textareaRef}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="어떤 도움이 필요하신가요?"
            disabled={isStreaming}
            rows={1}
          />
          <button 
            className="send-button" 
            onClick={sendMessage} 
            disabled={isStreaming || !input.trim()}
          >
            <svg className="send-icon" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
              <path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/>
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
}

export default App;
